const ToeflSpeaking = () => {
    const timeComponentRef = useRef();
    const readingSectRef = useRef();
    const listenSectRef = useRef();
    const [ taskState, setTaskState ] = useState("Task 1");
    const listenSectReadRef = useRef();
    let [currentScreenMedia, setCurrentScreenMedia ] = useState(null);

    const {
        recordingStatus,
        recordingTime,
        startRecording,
        stopRecording,
        getBlob,
        saveRecording,
      } = useAudioRecorder();

    useEffect(() => {
    // if (recordingStatus === 'stopped') {
    //     onStop?.(getBlob());
    // }
    }, [recordingStatus]);

    const beepAndStartRecording = () => {
        // TODO
        const audio = new Audio("/BlogPage/resources/sounds/beep-03.wav");
        audio.play();
        startRecording(currentScreenMedia);
    }

    const stopAndSaveAudio = () => {
        stopRecording((blob) => {
            const audio = new Audio("/BlogPage/resources/sounds/beep-03.wav");
            audio.play();    
            const a = document.createElement('a');
            a.download = (new Date()).toLocaleTimeString("en-US") + '.wav';
            a.href = URL.createObjectURL(blob);
            a.addEventListener('click', (e) => {
                setTimeout(() => URL.revokeObjectURL(a.href), 30 * 1000);
            });
            a.click();
          });
    }

    const onReadingSectionUpload = (evt) => {
        var files = evt.target.files;
        var file = files[0];

        const reader = new FileReader();
        reader.onload = () => {
            readingSectRef.current.setReadingSect(reader.result);
        };
        reader.onerror = () => {
        };
        reader.readAsText(file);
    }

    const onListenSectionUpload = (evt) => {
        var files = evt.target.files;
        listenSectRef.current.setAudioFile(files[0]);
    }

    const onListenSectionReadUpload = (evt) => {
        var files = evt.target.files;
        var file = files[0];

        const reader = new FileReader();
        reader.onload = () => {
            console.log(listenSectReadRef);
            listenSectReadRef.current.setReadingSect(reader.result);
        };
        reader.onerror = () => {
        };
        reader.readAsText(file);
    }

    const onTargetTabBtnClick = () => {
        navigator.mediaDevices.getDisplayMedia({
            video: {
                cursor: "never"
            },
            audio: {
                echoCancellation: true,
                noiseSuppression: true,
                sampleRate: 44100
            },
            systemAudio: "include"
        }).then((screenMedia) => {
            setCurrentScreenMedia(screenMedia);
        });
    }

    const onStartBtnClick = () => {
        if (taskState === "Task 1") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3);
            timeComponentRef.current.addPendingDuration(15);
            timeComponentRef.current.startNextCountdown();
        } else if (taskState === "Task 2" || taskState === "Task 3") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3);
            timeComponentRef.current.addPendingDuration(45);
            timeComponentRef.current.startNextCountdown();
        }
    }

    const onPrepareBtnClick = () => {
        if (taskState === "Task 1") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3);
            timeComponentRef.current.addPendingDuration(15);
            timeComponentRef.current.startNextCountdown();
        } else if (taskState === "Task 2" || taskState === "Task 3") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3);
            timeComponentRef.current.addPendingDuration(30);
            timeComponentRef.current.startNextCountdown();
        } else if (taskState === "Task 4") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3);
            timeComponentRef.current.addPendingDuration(20);
            timeComponentRef.current.startNextCountdown();
        }
    }

    const onSpeakingBtnClick = () => {
        if (taskState === "Task 1") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3, beepAndStartRecording);
            timeComponentRef.current.addPendingDuration(45, stopAndSaveAudio);
            timeComponentRef.current.startNextCountdown();
        } else if (taskState === "Task 2" || taskState === "Task 3" || taskState === "Task 4") {
            timeComponentRef.current.clearPendingDuration();
            timeComponentRef.current.addPendingDuration(3, beepAndStartRecording);
            timeComponentRef.current.addPendingDuration(60, stopAndSaveAudio);
            timeComponentRef.current.startNextCountdown();
        }
    }

    const setTaskCategory = (event) => {
        if (event.target.value) {
            console.log(event.target.value);
            setTaskState(event.target.value);
        }
    }

    return (
        <div className="text-center">
            <div className="block border-black border p-5" onChange={setTaskCategory}>
                <div className="flex container">
                    <div className="flex-1">
                        <input type="radio" id="radio_task1" name="fav_language" value="Task 1" defaultChecked={true} />
                        <label htmlFor="radio_task1">Task 1</label>
                    </div>
                    <div className="flex-1">
                        <input type="radio" id="radio_task2" name="fav_language" value="Task 2" />
                        <label htmlFor="radio_task2">Task 2</label>
                    </div>
                    <div className="flex-1">
                        <input type="radio" id="radio_task3" name="fav_language" value="Task 3" />
                        <label htmlFor="radio_task3">Task 3</label>
                    </div>
                    <div className="flex-1">
                        <input type="radio" id="radio_task4" name="fav_language" value="Task 4" />
                        <label htmlFor="radio_task4">Task 4</label>
                    </div>
                </div>

            </div>
            <div className="p-5">
                <label htmlFor="reading_sec_upload">Reading: </label>
                <input type="file" id="reading_sec_upload" name="reading_sec_upload" accept="text/markdown" onChange={onReadingSectionUpload} />
                
                <label htmlFor="listen_sec_upload">Listening: </label>
                <input type="file" id="listen_sec_upload" name="listen_sec_upload" accept="audio/*" onChange={onListenSectionUpload} />
                <label htmlFor="listen_sec_upload">Listening (Read): </label>
                <input type="file" id="listen_sec_read_upload" name="listen_sec_read_upload" accept="text/markdown" onChange={onListenSectionReadUpload} />
            </div>
            <p>
                <input type="button" onClick={onTargetTabBtnClick} value="Target tab" className="text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 me-2 mb-2 dark:bg-blue-600 dark:hover:bg-blue-700 focus:outline-none dark:focus:ring-blue-800"/>

                {(taskState !== "Task 1" && taskState !== "Task 4") ? <input type="button" onClick={onStartBtnClick} value="Start" className="text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 me-2 mb-2 dark:bg-blue-600 dark:hover:bg-blue-700 focus:outline-none dark:focus:ring-blue-800"/>: ""}
                <input type="button" onClick={onPrepareBtnClick} value="Preparing" className="text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 me-2 mb-2 dark:bg-blue-600 dark:hover:bg-blue-700 focus:outline-none dark:focus:ring-blue-800"/>
                {currentScreenMedia === null ? 
                    <input type="button" disabled onClick={onSpeakingBtnClick} value="Speaking" className="text-white bg-gray-700 font-medium rounded-lg text-sm px-5 py-2.5 me-2 mb-2"/>:
                    <input type="button" onClick={onSpeakingBtnClick} value="Speaking" className="text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 me-2 mb-2 dark:bg-blue-600 dark:hover:bg-blue-700 focus:outline-none dark:focus:ring-blue-800"/>
                }
                
            </p>
            <div>
                Countdown: <TimeComponent ref={timeComponentRef} />
            </div>
            <div className="flex justify-evenly p-3">
                <div className="block w-full p-2">
                    <ReadingSectComponent ref={readingSectRef} />
                </div>
                <div className="block w-full p-2">
                    <ReadingSectComponent ref={listenSectReadRef} >
                        <ListenSectComponent ref={listenSectRef} >
                        </ListenSectComponent>
                    </ReadingSectComponent>
                </div>
            </div>
        </div>
    )
}

